    "title": "日本超市促销传单",
    "description": "「一张热闹迷人的超市折叠传单的图片。顶部是一个大字母，上面写着“特价”和本周的日期。色彩缤纷的产品照片（蔬菜、水果、牛肉、鲜鱼）、红框价格标签、捕捉“超级史诗产品”和“家居用品” …… ”",
