    "model": "gpt-image-2",
    "prompt": "电影级宽幅航拍视角：热带海滨城市在日落时遭遇猛烈风暴，画面左侧是黑暗风暴云，右侧是炽烈金色阳光，形成强烈分裂。屋顶上有一架飞机或小型飞行器，周围高楼、棕榈树、海岸线和雨幕清晰可见。闪电、飞散雨水、反光街道和云层体积光增强戏剧性。整体要宏大、真实、紧张，像灾难电影概念海报。",
