    "description": "一幅精致的动漫风格横幅插画，采用梦幻紫罗兰色调，宽幅电影感构图，呈现黄昏时分一间安静的文学房间。画面右侧，一位名叫 {argument name=\"角色名\" default=\"Yuri\"} 的美丽少女动漫角色坐在大窗旁",
